#include <bits/stdc++.h>
using namespace std;using U=uint64_t;int n;vector<pair<int,int>> es;U a[64]{};int bal[64]{};long long checked=0;int minGap=1000000;
int gap(){int g=0;for(int i=0;i<n;i++){U s=0,b=a[i];while(b){int j=__builtin_ctzll(b);b&=b-1;s|=a[j];}s&=~(a[i]|(1ULL<<i));g+=__builtin_popcountll(s)-__builtin_popcountll(a[i]);}return g;}
void dfs(int k){if(k==(int)es.size()){for(int i=0;i<n;i++)if(bal[i])return;checked++;int g=gap();minGap=min(minGap,g);if(g<0){cout<<"COUNTEREXAMPLE "<<n<<' '<<g<<endl;for(int i=0;i<n;i++)cout<<a[i]<<' ';exit(1);}return;}auto [i,j]=es[k];dfs(k+1);a[i]|=1ULL<<j;bal[i]++;bal[j]--;dfs(k+1);a[i]=0| (a[i]&~(1ULL<<j));bal[i]--;bal[j]++;a[j]|=1ULL<<i;bal[j]++;bal[i]--;dfs(k+1);a[j]&=~(1ULL<<i);bal[j]--;bal[i]++;}
int main(){for(n=1;n<=6;n++){es.clear();checked=0;minGap=100000;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)es.push_back({i,j});dfs(0);cout<<"all labeled oriented Eulerian n="<<n<<" count="<<checked<<" minGap="<<minGap<<endl;}
mt19937 rng(210);for(int size:{8,12,16,24,32,48,63}){n=size;checked=0;minGap=100000;for(int t=0;t<10000;t++){fill(a,a+64,0);for(int step=0;step<3*n;step++){int k=3+rng()%min(n-2,8);vector<int>v(n);iota(v.begin(),v.end(),0);shuffle(v.begin(),v.end(),rng);bool ok=1;for(int j=0;j<k;j++)if((a[v[j]]>>v[(j+1)%k]&1)||(a[v[(j+1)%k]]>>v[j]&1))ok=0;if(ok)for(int j=0;j<k;j++)a[v[j]]|=1ULL<<v[(j+1)%k];}int g=gap();minGap=min(g,minGap);checked++;if(g<0){cout<<"COUNTEREXAMPLE "<<n<<' '<<g<<endl;return 1;}}cout<<"cycle union random n="<<n<<" count="<<checked<<" minGap="<<minGap<<endl;}}
